using System.Runtime.CompilerServices;namespace Challenge;public record Row(string Id,string Name);public static class Exporter{public static async IAsyncEnumerable<string> Export(IAsyncEnumerable<Row> source,[EnumeratorCancellation]CancellationToken ct=default){var all=new List<Row>();await foreach(var x in source.WithCancellation(ct))all.Add(x);foreach(var x in all)yield return $"{x.Id},{x.Name}";}}
